using HRIS.Api.Common; using HRIS.Api.DTOs.Parking; using HRIS.Api.Exceptions; using HRIS.Api.Models; using HRIS.Api.Repositories;
namespace HRIS.Api.Services; public class ParkingService:IParkingService { private readonly IParkingRepository _repo; private readonly IApprovalService _approval; private readonly IReferenceRepository _refs; private readonly IAuditLogService _audit; public ParkingService(IParkingRepository repo,IApprovalService approval,IReferenceRepository refs,IAuditLogService audit){_repo=repo;_approval=approval;_refs=refs;_audit=audit;} public async Task<List<VehicleTypeOption>> GetVehicleTypesAsync()=>(await _repo.GetVehicleTypesAsync()).Select(x=>new VehicleTypeOption(x.Id,x.Name)).ToList(); public async Task<List<ParkingResponseDto>> GetAsync(UserContext actor){var rows=await _repo.GetAllAsync(actor.IsHrOrSupport?null:actor.EmployeeId);var apps=await _approval.GetByRefsAsync(ApprovalRequestTypes.Parking,rows.Select(x=>x.Id),actor);return rows.Select(x=>ToDto(x,apps.GetValueOrDefault(x.Id)?.Id)).ToList();} public async Task<ParkingResponseDto> CreateAsync(ParkingCreateDto dto,UserContext actor){var emp=actor.EmployeeId??throw new ForbiddenException("Akun ini tidak terhubung ke Employee.");if(!await _refs.ExistsAsync<VehicleType>(dto.VehicleTypeId))throw new BadRequestException("VehicleTypeId tidak ditemukan.");var plate=dto.PlateNumber.Trim().ToUpperInvariant();if(await _repo.ActivePlateExistsAsync(plate))throw new BadRequestException("Nomor polisi sudah terdaftar pada registrasi aktif.");var x=await _repo.AddAsync(new ParkingRegistration{EmployeeId=emp,VehicleTypeId=dto.VehicleTypeId,PlateNumber=plate,Status="Pending"});var app=await _approval.SubmitAsync(ApprovalRequestTypes.Parking,x.Id,emp,$"Registrasi parkir {plate}");return ToDto(await _repo.GetByIdAsync(x.Id)!,app.Id);} public async Task UpdateStatusAsync(int id,string status,UserContext actor){if(!actor.IsHrOrSupport)throw new ForbiddenException("Hanya HR/Support yang boleh mengubah status parkir.");var x=await _repo.GetByIdAsync(id)??throw new NotFoundException("Registrasi parkir tidak ditemukan.");status=status.Trim();if(status=="CardReady"){if(x.Status!="Approved")throw new BadRequestException("Kartu hanya bisa disiapkan setelah approval.");x.Status=status;x.CardReadyAt=DateTime.UtcNow;}else if(status=="Collected"){if(x.Status!="CardReady")throw new BadRequestException("Kartu belum berstatus siap diambil.");x.Status=status;x.CardCollectedAt=DateTime.UtcNow;}else throw new BadRequestException("Status hanya CardReady atau Collected.");await _repo.UpdateAsync(x);if(actor.IsSupport)await _audit.LogAsync(actor.UserId,"Parking.Status",nameof(ParkingRegistration),id,$"Status menjadi {status}");} private static ParkingResponseDto ToDto(ParkingRegistration x,int? aid)=>new(){Id=x.Id,EmployeeId=x.EmployeeId,EmployeeName=x.Employee?.FullName??"",VehicleTypeId=x.VehicleTypeId,VehicleTypeName=x.VehicleType?.Name??"",PlateNumber=x.PlateNumber,Status=x.Status,CardReadyAt=x.CardReadyAt,CardCollectedAt=x.CardCollectedAt,CreatedAt=x.CreatedAt,ApprovalId=aid}; }
